<script setup lang="ts">
import { computed } from 'vue';
import { Close } from '@element-plus/icons-vue';
import { canvasLabels,type CanvasNode,type CanvasData } from '@/utils/dramaCanvas';
import type { GetSessionListVO } from '@/api/model/types';
import type { ShortDramaCharacter,ShortDramaStoryboard } from '@/api/shortDrama/types';
import type { FlowShotState } from './types';
import CharacterVoice from '../CharacterVoice.vue';
import ShotVideoPanel from '../ShotVideoPanel.vue';
import GeneratedAssetImage from '../GeneratedAssetImage.vue';
import ShotVideoResolution from '../ShotVideoResolution.vue';
const props=defineProps<{node:CanvasNode;nodes:CanvasNode[];inputs:CanvasNode[];projectId:string;imageModels:GetSessionListVO[];videoModels:GetSessionListVO[];busy:boolean;error:string;shot?:ShortDramaStoryboard;state?:FlowShotState;actor?:ShortDramaCharacter}>();
const emit=defineEmits<{patch:[data:Partial<CanvasData>];close:[];save:[];generate:[];query:[];accept:[];upload:[event:Event];removeInput:[id:string];connect:[source:string];restore:[];plan:[]}>();
const models=computed(()=>props.node.kind==='image' ? props.imageModels : props.videoModels);
const roles=computed(()=>props.nodes.filter(n=>n.kind==='image'&&n.data.purpose==='character'));
function change(key:keyof CanvasData,value:unknown){emit('patch',{[key]:value});}
function resolution(value:string){try{change('resolution',JSON.parse(value).video_resolution);}catch{/* output component validates its own value */}}
</script>
<template>
  <aside class="canvas-inspector" aria-label="节点编辑器">
    <header class="inspector-heading"><div><small>{{canvasLabels[node.kind]}}节点</small><h2>{{node.data.title}}</h2></div><button aria-label="关闭节点编辑器" @click="emit('close')"><el-icon><Close/></el-icon></button></header>
    <div class="inspector-content">
      <el-form label-position="top">
        <el-form-item label="节点名称"><el-input :model-value="node.data.title" aria-label="编辑节点名称" @update:model-value="change('title',$event)"/></el-form-item>
        <template v-if="node.kind==='group'"><el-form-item label="分组宽度"><el-input-number :model-value="node.data.width" :min="320" :max="6000" aria-label="分组宽度" @update:model-value="change('width',$event)"/></el-form-item><el-form-item label="分组高度"><el-input-number :model-value="node.data.height" :min="220" :max="6000" aria-label="分组高度" @update:model-value="change('height',$event)"/></el-form-item></template>
        <template v-else>
          <el-form-item v-if="['text','script','video'].includes(node.kind) || (node.kind==='audio' && !actor)" :label="node.kind==='script' ? '剧本正文' : node.kind==='audio' ? '样音正文' : node.kind==='video' ? '镜头内容' : '文本正文'"><el-input :model-value="node.data.content" type="textarea" :rows="node.kind==='script' ? 12 : 4" aria-label="节点正文" @update:model-value="change('content',$event)"/></el-form-item>
          <el-form-item v-if="node.kind==='image'" label="图片用途"><el-select :model-value="node.data.purpose" aria-label="图片用途" :disabled="!!node.data.business" @update:model-value="change('purpose',$event)"><el-option label="角色造型" value="character"/><el-option label="拍摄场景" value="location"/><el-option label="固定道具" value="prop"/><el-option label="首帧参考（可选）" value="frame"/></el-select></el-form-item>
          <el-form-item v-if="node.kind==='audio'" label="所属角色"><el-select :model-value="inputs.find(n=>n.kind==='image' && n.data.purpose==='character')?.id || node.data.actorNodeId" :disabled="inputs.some(n=>n.kind==='image')" aria-label="声音所属角色" @update:model-value="change('actorNodeId',$event)"><el-option v-for="n in roles" :key="n.id" :label="n.data.title" :value="n.id"/></el-select></el-form-item>
          <el-form-item v-if="node.kind!=='text' && (node.kind!=='audio' || !actor)" :label="node.kind==='video' ? '视频导演描述' : node.kind==='audio' ? '声音描述' : node.kind==='script' ? '生成或改写要求' : '图片描述'"><el-input :model-value="node.data.prompt" type="textarea" :rows="node.kind==='video' ? 10 : 5" :placeholder="node.kind==='video' ? '写清动作、原对白、摄影、声音与交镜承接' : '输入本节点的创作要求'" aria-label="节点提示词" @update:model-value="change('prompt',$event)"/></el-form-item>
          <template v-if="node.kind==='image'"><el-form-item label="参考图片"><el-input :model-value="node.data.url" placeholder="已上传的 HTTPS 图片地址" aria-label="节点图片地址" @update:model-value="change('url',$event)"/><label class="upload-button">上传参考图<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="busy" aria-label="上传节点参考图" @change="emit('upload',$event)"/></label></el-form-item><GeneratedAssetImage v-if="node.data.url" :src="node.data.url" :title="node.data.title" /></template>
          <el-form-item v-if="['image','video'].includes(node.kind)" label="生成模型"><el-select :model-value="node.data.model" filterable aria-label="节点生成模型" @update:model-value="change('model',$event)"><el-option v-for="m in models" :key="m.modelName" :label="m.modelDescribe || m.modelName" :value="m.modelName || ''"/></el-select></el-form-item>
          <template v-if="node.kind==='video'"><el-form-item label="镜头顺序"><el-input-number :model-value="node.data.order" :min="1" aria-label="画布镜头顺序" @update:model-value="change('order',$event)"/></el-form-item><el-form-item label="视频秒数（可选）"><el-input-number :model-value="node.data.seconds" :min="-1" :max="360" :precision="0" placeholder="模型默认" aria-label="节点视频秒数" @update:model-value="change('seconds',$event)"/></el-form-item><ShotVideoResolution :continuity-json="JSON.stringify({video_resolution:node.data.resolution || '720p'})" :model="node.data.model" @update="resolution"/><el-checkbox :model-value="node.data.useStartFrame || false" @update:model-value="change('useStartFrame',$event)">使用已连接的首帧</el-checkbox></template>
        </template>
      </el-form>
      <section v-if="node.kind!=='group'" class="input-section"><h3>输入与引用 <small>{{inputs.length}}</small></h3><div v-for="source in inputs" :key="source.id" class="input-item"><span>{{canvasLabels[source.kind]}} · {{source.data.title}}<small v-if="source.kind==='video'">前后镜头顺序</small></span><button :aria-label="`移除${source.data.title}连线`" @click="emit('removeInput',source.id)">×</button></div><el-select v-if="node.kind!=='text'" placeholder="添加输入节点" aria-label="添加节点输入" :model-value="''" @update:model-value="emit('connect',$event)"><el-option v-for="source in nodes.filter(n=>n.id!==node.id && n.kind!=='group' && !inputs.some(i=>i.id===n.id))" :key="source.id" :label="`${canvasLabels[source.kind]} · ${source.data.title}`" :value="source.id"/></el-select></section>
      <CharacterVoice v-if="node.kind==='audio'&&actor" :project-id="projectId" :character="actor" />
      <p v-else-if="node.kind==='audio'" class="editor-hint">选择角色并保存到项目后，可在这里生成、上传、试听和选用样音。</p>
      <ShotVideoPanel v-if="shot&&state" :shot="shot" :preview-src="state.previewSrc" :blocked="state.blocked" :unknown="state.unknown" :hint="state.hint" :can-restore="state.canRestore" :disabled="busy" @query="emit('query')" @restore="emit('restore')"/>
      <section v-if="node.data.job" class="job-result"><h3>图片任务 · {{node.data.job.status}}</h3><GeneratedAssetImage v-if="node.data.job.url" :src="node.data.job.url" :title="`${node.data.title}候选`" :model="node.data.job.model" :prediction-id="node.data.job.id"/><el-button :disabled="busy" @click="emit('query')">查询原任务</el-button><el-button v-if="node.data.job.url && node.data.purpose!=='prop'" type="primary" :disabled="busy" @click="emit('accept')">选用候选图片</el-button></section>
      <p v-if="error" role="alert" class="editor-error">{{error}}</p>
      <p class="editor-hint">画布自动保存。保存到项目后，生成沿用项目的审阅规则与原任务记录。</p>
    </div>
    <footer class="inspector-actions"><el-button :disabled="busy || ['text','group'].includes(node.kind)" :loading="busy" @click="emit('save')">保存到项目</el-button><el-button v-if="['script','image','video'].includes(node.kind)" type="primary" :disabled="busy || node.data.purpose==='frame' || (state?.blocked ?? false)" @click="emit('generate')">{{node.kind==='script' ? '生成 / 改写' : node.kind==='image' ? '生成图片' : shot?.videoStatus==='done' ? '生成新版本' : '生成视频'}}</el-button><el-button v-if="node.kind==='script'" :disabled="busy" @click="emit('plan')">分析资产与拆分镜头</el-button></footer>
  </aside>
</template>
<style scoped>
.canvas-inspector{width:360px;flex:none;display:flex;flex-direction:column;background:var(--drama-surface-strong);border-left:1px solid var(--drama-border);z-index:5;min-height:0}.inspector-heading{display:flex;align-items:flex-start;justify-content:space-between;padding:22px 20px 18px;border-bottom:1px solid var(--drama-border-subtle)}.inspector-heading small{font-size:10px;color:var(--drama-text-tertiary)}.inspector-heading h2{margin:8px 0 0;font-size:15px;line-height:1.5}.inspector-heading button{border:0;background:transparent;color:var(--drama-text-tertiary);cursor:pointer;padding:4px}.inspector-content{padding:22px 20px;overflow:auto;flex:1;min-height:0}.inspector-content :deep(.el-form-item__label){font-size:12px;color:var(--drama-text-secondary)}.inspector-content :deep(.el-form-item){margin-bottom:18px}.inspector-content :deep(.el-input-number){width:100%}.input-section,.job-result{margin:24px 0}.input-section h3,.job-result h3{font-size:12px;font-weight:600;margin:0 0 12px}.input-section h3 small{color:var(--drama-text-tertiary);margin-left:5px}.input-item{display:flex;justify-content:space-between;align-items:center;padding:10px;margin-bottom:6px;border-radius:6px;background:var(--drama-surface-muted);font-size:11px}.input-item small{display:block;color:var(--drama-text-tertiary);margin-top:4px}.input-item button{border:0;background:none;color:var(--drama-text-tertiary);cursor:pointer}.inspector-actions{display:flex;flex-wrap:wrap;gap:8px;padding:16px 20px;border-top:1px solid var(--drama-border)}.inspector-actions :deep(.el-button){margin:0;font-size:12px;flex:1}.editor-hint{font-size:11px;line-height:1.8;color:var(--drama-text-tertiary);margin:16px 0}.editor-error{color:var(--drama-danger);font-size:12px;line-height:1.8;overflow-wrap:anywhere}.upload-button{display:inline-flex;cursor:pointer;font-size:11px;color:var(--drama-primary);margin-top:8px}.upload-button input{display:none}.job-result :deep(.el-button){margin-top:12px}@media(max-width:900px){.canvas-inspector{position:absolute;right:0;top:0;bottom:0;width:min(360px,90vw);box-shadow:-8px 0 32px #202c4012}}
</style>
